    },
    update(t) { wide(I.shots.swing, t, durOf('swing')); },
    leave() { if (ctrl && inSee.own && ctrl.state !== 'CLOSED') inSee.off = true; }
  },
  finale: {
    enter() { introCam(); finAng = 0; },
