// Đạo diễn phía trang: mỗi cảnh = { setup(), update(t, dt), cleanup() } trên window.__app (trang chạy ?test).
// Node gọi __dir.begin(tên) → __dir.tick() mỗi khung (cập nhật camera / trạng thái rồi bước đồng hồ ảo).
(() => {
  const A = window.__app, DT = 1000 / 30;
  const clamp = (x, a = 0, b = 1) => Math.max(a, Math.min(b, x));
  const smooth = (k) => { k = clamp(k); return k * k * k * (k * (k * 6 - 15) + 10); };
  const sine = (k) => { k = clamp(k); return 0.5 - 0.5 * Math.cos(Math.PI * k); };
  const lerp = (a, b, k) => a + (b - a) * k;
  // Catmull-Rom qua các khóa [{p:[x,y,z], l:[x,y,z]}] theo u ∈ [0,1] (khóa cách đều)
  function cr(keys, u, f) {
    const n = keys.length - 1; if (n === 0) return keys[0][f].slice();
    const s = clamp(u) * n, i = Math.min(n - 1, Math.floor(s)), k = s - i;
    const P = (j) => keys[Math.max(0, Math.min(n, j))][f];
    const p0 = P(i - 1), p1 = P(i), p2 = P(i + 1), p3 = P(i + 2), out = [0, 0, 0];
    for (let d = 0; d < 3; d++) {
      const a = p0[d], b = p1[d], c = p2[d], e = p3[d];
      out[d] = 0.5 * ((2 * b) + (-a + c) * k + (2 * a - 5 * b + 4 * c - e) * k * k + (-a + 3 * b - 3 * c + e) * k * k * k);
    }
    return out;
  }
  function camMode() { A.cam.flight.then = null; A.cam.mode = 'intro'; A.controls.enabled = false; }
  function place(p, l, fov) {
    A.camera.position.set(p[0], p[1], p[2]); A.controls.target.set(l[0], l[1], l[2]); A.camera.lookAt(A.controls.target);
    if (fov && A.camera.fov !== fov) { A.camera.fov = fov; A.camera.updateProjectionMatrix(); }
  }
  // ease: 'smooth' (vào / ra êm), 'sine', 'lin', 'out' (giảm dần)
  const EASE = { smooth, sine, lin: clamp, out: (k) => 1 - Math.pow(1 - clamp(k), 2), in: (k) => Math.pow(clamp(k), 2) };
  function path(keys, t, dur, ease = 'sine') { const u = EASE[ease](t / dur); return [cr(keys, u, 'p'), cr(keys, u, 'l')]; }
  function setNight(v) { A.dayNight.night = v; A.dayNight.target = v; }
  const neutral = { temp: 27, rain: 0, wind: 0, gust: 0, windDir: 0, cloud: 0, haze: 0, level: 0, lightning: 0, closed: false, fog: 0 };
  function wx(p) { A.weather.setLive({ ...neutral, ...p }, true); }
  function wxOff() { if (A.weather.live) A.weather.setLive(null, true); A.weather.setPreset('now'); }
  const swing = () => A.songHan.ctrl;
  let st = 0;
  // ---------- tự lái (theo src/intro/scenes.ts) ----------
  const gAuto = (o) => (inp) => { inp.turn = (st >= o.turnFrom && st <= o.turnTo ? o.turn : 0); inp.climb = o.climb || 0; inp.throttle = 0; };
  const cAuto = (inp) => { inp.gas = 1; inp.brake = 0; inp.steer = 0; inp.hand = false; };
  const bAuto = (inp) => { inp.gas = 1; inp.brake = 0; inp.steer = 0; inp.hard = false; };
  let walkYaw = 0;
  const wAuto = (inp) => { inp.mz = 1; inp.mx = 0; inp.run = false; inp.camYaw = walkYaw; };

  const shots = {};
  // Cảnh camera tự do: keys, dur, night (số hoặc hàm t), ease, fov, wx, extra(t)
  function camShot(name, o) {
    shots[name] = {
      dur: o.dur, warm: o.warm ?? 45,
      setup() { camMode(); setNight(typeof o.night === 'function' ? o.night(0) : (o.night ?? 0)); if (o.wx) wx(o.wx); else wxOff(); if (o.setup) o.setup(); },
      update(t, dt) {
        if (typeof o.night === 'function') setNight(o.night(t));
        const [p, l] = path(o.keys, t, o.dur, o.ease); place(p, l, o.fov || 45); if (o.extra) o.extra(t, dt);
      },
      cleanup() { if (o.cleanup) o.cleanup(); }
    };
  }
  window.__dirShots = shots;
  window.__dirLib = { camShot, path, place, setNight, wx, wxOff, swing, smooth, sine, lerp, clamp, camMode, A,
    gAuto, cAuto, bAuto, wAuto, get st() { return st; }, set st(v) { st = v; }, get walkYaw() { return walkYaw; }, set walkYaw(v) { walkYaw = v; } };

  let cur = null, t = 0;
  window.__dir = {
    list: () => Object.keys(shots),
    begin(name) {
      if (cur && cur.cleanup) cur.cleanup();
      cur = shots[name]; if (!cur) throw new Error('no shot ' + name);
      t = 0; st = 0; window.__vt.enable(); cur.setup(); return { dur: cur.dur, warm: cur.warm, pre: cur.pre || 0 };
    },
    // warm: chạy khung không quay với t âm → 0 (cảnh tự lo trạng thái ở t < 0 nếu cần)
    tick(rec) { const dt = DT / 1000; st = t; cur.update(t, dt); window.__vt.step(DT); t += dt; return t; },
    setT(v) { t = v; },
    end() { if (cur && cur.cleanup) cur.cleanup(); cur = null; }
  };
})();

