// Danh sách cảnh quay (chạy trong trang sau director.js). Tọa độ: 1 đơn vị = 1 m, X Tây → Đông, −Z là Bắc.
// Cầu Rồng z = 0 (đầu rồng x ≈ +316), Cầu sông Hàn z = −1080, Trần Thị Lý z = +1300 (tháp x ≈ −130), Thuận Phước z = −2900.
(() => {
  const L = window.__dirLib, A = L.A, shots = window.__dirShots, { camShot, lerp, smooth } = L;

  /* ---------- 1. Mở đầu ---------- */
  camShot('open_aerial', { dur: 6.5, night: 0.0, ease: 'out', keys: [
    { p: [-460, 560, 2050], l: [0, 0, -300] },
    { p: [-300, 260, 1350], l: [10, -10, -100] },
    { p: [-170, 95, 860], l: [20, -20, 80] }] });
  camShot('open_night', { dur: 5, night: 1, ease: 'sine', keys: [
    { p: [-140, 40, 210], l: [60, 22, -20] },
    { p: [-230, 70, 260], l: [80, 18, -60] }] });

  /* ---------- 2. Bốn cách khám phá ---------- */
  shots.glider = {
    dur: 6, warm: 20,
    setup() { L.setNight(0); L.wxOff(); A.explore.start({ pos: [0, 80, 240], yaw: Math.PI / 2 }); A.explore.auto = L.gAuto({ turnFrom: 4.4, turnTo: 5.2, turn: 1, climb: 0 }); },
    update() {}, cleanup() { A.explore.auto = null; A.explore.stop(); }
  };
  shots.car = {
    dur: 6, warm: 20,
    setup() { L.setNight(0); L.wxOff(); A.drive.start(); A.drive.auto = L.cAuto; },
    update(t) { const c = A.drive.cam, e = smooth(t / 4); c.yaw = lerp(1.0, 0, e); c.pitch = 0.3 * (1 - e); c.idle = 0; },
    cleanup() { A.drive.auto = null; A.drive.stop(); }
  };
