// Quay cảnh từ trang thật bằng đồng hồ ảo: node record.mjs [--preview[=N]] [--url=...] shot1 shot2 ... | all
//  --preview: chỉ lưu 1 khung mỗi N (mặc định 15) vào work/preview/<cảnh>.jpg (lưới), không ghi clip
//  mặc định: ghi shared/source-footage/<cảnh>.mp4 (1920×1080, 30 fps, H.264 crf 12)
import { createRequire } from 'node:module';
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const require = createRequire('D:/2026 - Tuan/danang-vite/package.json');
const { chromium } = require('playwright');

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');
const argv = process.argv.slice(2);
const opt = (k, d) => { const a = argv.find((x) => x.startsWith('--' + k)); if (!a) return d; const v = a.split('=')[1]; return v === undefined ? true : v; };
const PREVIEW = opt('preview', false), EVERY = PREVIEW === true ? 15 : Number(PREVIEW) || 15;
const URL_ = opt('url', 'https://danangbridges.netlify.app/?test');
let names = argv.filter((x) => !x.startsWith('--'));
const W = 1920, H = 1080;
const OUT = path.join(ROOT, 'shared', 'source-footage'), PRE = path.join(ROOT, 'work', 'preview');
fs.mkdirSync(OUT, { recursive: true }); fs.mkdirSync(PRE, { recursive: true });

const args = ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit', '--autoplay-policy=no-user-gesture-required'];
const browser = await chromium.launch({ headless: true, args });
const page = await browser.newPage({ viewport: { width: W, height: H }, deviceScaleFactor: 1 });
page.setDefaultTimeout(600000);
page.on('pageerror', (e) => console.log('[pageerror]', String(e).slice(0, 300)));
page.on('console', (m) => { if (m.type() === 'error') console.log('[console]', m.text().slice(0, 200)); });
await page.addInitScript({ path: path.join(HERE, 'vclock.js') });
const t0 = Date.now();
await page.goto(URL_, { waitUntil: 'load', timeout: 300000 });
await page.waitForFunction(() => window.__app && (() => { const l = document.getElementById('loading'); return !l || getComputedStyle(l).display === 'none' || l.classList.contains('hide') || getComputedStyle(l).opacity === '0'; })(), null, { timeout: 300000 });
await page.addStyleTag({ content: 'body > *:not(#scene){visibility:hidden !important} *{cursor:none !important}' });
await page.waitForTimeout(6000);   // khung thật cho prewarm / tải nền
console.log('ready in', Date.now() - t0, 'ms');
await page.addScriptTag({ path: path.join(HERE, 'director.js') });
await page.addScriptTag({ path: path.join(HERE, 'shots.js') });
if (!names.length || names[0] === 'all') names = await page.evaluate(() => window.__dir.list());

for (const name of names) {
  const info = await page.evaluate((n) => window.__dir.begin(n), name);
  const pre = await page.evaluate(() => { const c = window.__app.cam.mode; return c; });
  await page.waitForTimeout(name.match(/glider|car|bike|walk/) ? 5000 : 300);   // tải mô hình (thời gian thật, đồng hồ ảo đứng)
  for (let i = 0; i < info.warm; i++) await page.evaluate(() => window.__dir.tick());
  const N = Math.round(info.dur * 30);
  const ts = Date.now();
  let ff = null;
  const prevFiles = [];
  if (!PREVIEW) {
    ff = spawn('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'image2pipe', '-framerate', '30', '-c:v', 'png', '-i', '-',
      '-c:v', 'libx264', '-preset', 'slow', '-crf', '12', '-pix_fmt', 'yuv420p', '-r', '30', path.join(OUT, name + '.mp4')], { stdio: ['pipe', 'inherit', 'inherit'] });
  }
  for (let i = 0; i < N; i++) {
    await page.evaluate(() => window.__dir.tick());
    if (PREVIEW) {
      if (i % EVERY === 0 || i === N - 1) { const f = path.join(PRE, `${name}_${String(i).padStart(4, '0')}.jpg`); await page.screenshot({ path: f, type: 'jpeg', quality: 80 }); prevFiles.push(f); }
    } else {
      const buf = await page.screenshot({ type: 'png' });
      if (!ff.stdin.write(buf)) await new Promise((r) => ff.stdin.once('drain', r));
    }
  }
  if (ff) { ff.stdin.end(); await new Promise((r) => ff.on('close', r)); }
  else {
    // lưới xem nhanh
    const cols = 4, list = prevFiles.map((f) => `file '${f.replace(/\\/g, '/')}'`).join('\n');
    const lf = path.join(PRE, name + '.txt'); fs.writeFileSync(lf, list);
    await new Promise((r) => spawn('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'concat', '-safe', '0', '-i', lf, '-vf', `scale=480:270,tile=${cols}x${Math.ceil(prevFiles.length / cols)}`, '-frames:v', '1', path.join(PRE, name + '.jpg')], { stdio: 'inherit' }).on('close', r));
    for (const f of prevFiles) fs.unlinkSync(f); fs.unlinkSync(lf);
  }
  console.log(`${name}: ${N} khung, ${((Date.now() - ts) / 1000).toFixed(1)} s, cam ${pre}`);
}
await page.evaluate(() => window.__dir.end());
await browser.close();

