// node overlays.mjs → shared/assets/overlays/<lang>/<id>.png
import { createRequire } from 'node:module';
import fs from 'node:fs';
const require = createRequire('D:/2026 - Tuan/danang-vite/package.json');
const { chromium } = require('playwright');
const spec = JSON.parse(fs.readFileSync(new URL('./overlays.json', import.meta.url))).items;
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500&family=Be+Vietnam+Pro:wght@300;400;500;600&family=JetBrains+Mono:wght@400;500&display=block');
html,body{margin:0;width:1920px;height:1080px;background:transparent;overflow:hidden}
*{box-sizing:border-box}
.gold{color:#e8c172}
.d{font-family:'Cormorant Garamond',serif}.b{font-family:'Be Vietnam Pro',sans-serif}.m{font-family:'JetBrains Mono',monospace}
.shadow{text-shadow:0 2px 6px rgba(0,0,0,.55),0 6px 40px rgba(0,0,0,.45)}
.wrap{position:absolute;inset:0}
.hero{position:absolute;left:0;right:0;top:330px;text-align:center;color:#fbf3e4;font-weight:600;font-size:176px;letter-spacing:.17em;padding-left:.17em;line-height:1}
.heroSub{position:absolute;left:0;right:0;top:560px;display:flex;justify-content:center;align-items:center;gap:34px;color:#fbf3e4;font-weight:400;font-size:29px;letter-spacing:.42em}
